function Modal({isOpen = false, onRequestClose,  children}){

  if(!isOpen) return null

  const handleClose = e => {
    if(e.target.classList.contains('modal')){
      onRequestClose && onRequestClose()
    }
  }

  return (
    <Reveal.Fade>
      <div className='modal' onClick={handleClose}>
        {children}
      </div>
    </Reveal.Fade>
  )
}

